{
  "schemaVersion": "0.2",
  "slug": "sparkline",
  "name": "Sparkline",
  "family": "F",
  "status": "experimental",
  "purpose": "Renders a miniature trend line for inline placement beside metrics.",
  "scenarios": [
    "Trend beside a KPI value",
    "Inline table cell trend",
    "Compact performance hint"
  ],
  "props": {
    "data": {
      "type": "string",
      "required": true,
      "description": "Array of numeric samples in order."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible description of the trend."
    },
    "width": {
      "type": "number",
      "required": false,
      "description": "SVG viewport width in px.",
      "default": 96
    },
    "height": {
      "type": "number",
      "required": false,
      "description": "SVG viewport height in px.",
      "default": 28
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Trend line rendered."
    },
    {
      "name": "empty",
      "description": "No samples provided."
    }
  ],
  "composition": {
    "allowedParents": [
      "statistic",
      "kpi-dashboard",
      "table",
      "card"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not add axes or legends to a sparkline; use Chart.",
    "Do not render a sparkline with fewer than two samples."
  ],
  "a11y": {
    "role": "img",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "aria-label summarizes the trend direction.",
    "wcag": [
      "1.1.1"
    ]
  },
  "responsive": {
    "strategy": "Fixed intrinsic size; does not stretch.",
    "breakpoints": {
      "compact": "Intrinsic size.",
      "medium": "Intrinsic size.",
      "large": "Intrinsic size."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "sparkline",
    "states": [
      "default",
      "empty"
    ],
    "intents": [
      "visualize-data"
    ]
  },
  "mechanics": "Sparkline is a compact SVG polyline. Samples are downsampled to at most the pixel width so a 4k feed does not emit 4k SVG points.",
  "usage": [
    "Import Sparkline from @chameleon-ui/components-react. Pass data and an accessible label.",
    "Place beside a metric. Use Chart when axes and a legend are required."
  ]
}

import './styles.css'
import { downsample } from '../virtual/downsample.js'

export interface SparklineProps {
  data: number[]
  label: string
  width?: number
  height?: number
  className?: string
}

export function Sparkline({ data, label, width = 96, height = 28, className }: SparklineProps) {
  const classes = ['cu-sparkline', className].filter(Boolean).join(' ')
  const samples = downsample(data, Math.max(2, Math.floor(width)))

  if (samples.length < 2) {
    return (
      <span className={classes} data-ai-role="sparkline" data-ai-intent="visualize-data" data-ai-state="empty" aria-label={label} role="img" />
    )
  }

  const min = Math.min(...samples)
  const max = Math.max(...samples)
  const span = max - min || 1
  const step = width / (samples.length - 1)
  const points = samples
    .map((value, index) => `${index * step},${height - ((value - min) / span) * height}`)
    .join(' ')

  return (
    <svg
      className={classes}
      data-ai-role="sparkline" data-ai-intent="visualize-data"
      data-ai-state="default"
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      role="img"
      aria-label={label}
    >
      <polyline className="cu-sparkline__line" points={points} />
    </svg>
  )
}

.cu-sparkline {
  display: inline-block;
  vertical-align: middle;
  contain: strict;
}

.cu-sparkline__line {
  fill: none;
  stroke: var(--cu-color-palette-brand);
  stroke-width: 1.5;
}
